#!/usr/bin/env python3
import numpy as np, math, json, os, sys, random, statistics

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def isco_radius(M):
    """Prograde ISCO radius for a non-rotating BH (a=0):
    r_ISCO = 6 * GM / c**2 = 3 * r_s"""
    return 3 * schwarzschild_radius(M)

def orbital_frequency(r, a=0.0):
    """Keplerian orbital frequency (non-spinning, Newtonian approximation)
    Omega = sqrt(G*M / r^3)"""
    return math.sqrt(G * M_sun / r**3)

def test_hypothesis():
    # Example: compute Schwarzschild ISCO and Keplerian frequency for a 10 solar‑mass black hole
    M = 10 * M_sun
    r_isco = isco_radius(M)
    omega = orbital_frequency(r_isco, a=0.0)
    print(f"ISCO radius (non‑rotating): {r_isco:.3e} m")
    print(f"Orbital frequency at ISCO: {omega:.3e} rad/s")

if __name__ == "__main__":
    test_hypothesis()

