import os, json, math

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

# Helper to load a GWTC catalog (expects environment variable GWTC_CATALOG_PATH)
def load_catalog(path):
    try:
        import json
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"Failed to load catalog: {e}")
        sys.exit(1)

def main():
    catalog_path = os.getenv('GWTC_CATALOG_PATH')
    if not catalog_path:
        print('Environment variable GWTC_CATALOG_PATH not set')
        sys.exit(1)
    data = load_catalog(catalog_path)
    events = data.get('events', [])
    total = len(events)
    print(f"Total number of events in catalog: {total}")

if __name__ == "__main__":
    main()

